CREATE TABLE IF NOT EXISTS biz_jobs(job_id TEXT PRIMARY KEY,user_id TEXT NOT NULL,domain TEXT NOT NULL,city TEXT,district TEXT,idempotency_key TEXT NOT NULL,input_json TEXT NOT NULL,principal_json TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,lease_owner TEXT,lease_until INTEGER,available_at INTEGER NOT NULL DEFAULT 0,analysis_run_id TEXT UNIQUE,metric_value REAL,result_json TEXT,error TEXT,created_at INTEGER NOT NULL,UNIQUE(user_id,domain,idempotency_key));
CREATE TABLE IF NOT EXISTS biz_workflow_tickets(ticket_id TEXT PRIMARY KEY,job_id TEXT NOT NULL UNIQUE,user_id TEXT NOT NULL,domain TEXT NOT NULL,city TEXT,district TEXT,status TEXT NOT NULL,approved_by TEXT NOT NULL,opened_at INTEGER NOT NULL,resolved_at INTEGER);
CREATE TABLE IF NOT EXISTS biz_retests(retest_id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL,source_record_id TEXT NOT NULL,value REAL NOT NULL,measured_at INTEGER NOT NULL,submitted_by TEXT NOT NULL,status TEXT NOT NULL,evidence_json TEXT NOT NULL,UNIQUE(ticket_id,source_record_id));
CREATE TABLE IF NOT EXISTS biz_outbox(event_id TEXT PRIMARY KEY,job_id TEXT NOT NULL,user_id TEXT NOT NULL,domain TEXT NOT NULL,channel TEXT NOT NULL,status TEXT NOT NULL,payload_json TEXT NOT NULL,created_at INTEGER NOT NULL,delivered_at INTEGER,UNIQUE(job_id,channel));
CREATE TABLE IF NOT EXISTS biz_inbox(message_id TEXT PRIMARY KEY,user_id TEXT NOT NULL,domain TEXT NOT NULL,payload_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS biz_job_schedules(schedule_id TEXT PRIMARY KEY,user_id TEXT NOT NULL,domain TEXT NOT NULL,input_json TEXT NOT NULL,principal_json TEXT NOT NULL,interval_sec INTEGER NOT NULL,next_at INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1);
